<?php

function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        if ($a['age'] == $b['age']) {
            return 0;
        }

        return ($a['age'] < $b['age']) ? -1 : 1;
    });

    switch ($order) {
        case 'asc':
            return $set;
            break;
        case 'desc':
            $sorted_set = [];
            foreach ($set as $key => $value) {
                $sorted_set[] = $value;
            }
            usort($sorted_set, function ($a, $b) use ($order) {
                if ($a['age'] == $b['age']) {
                    return 0;
                }

                return ($a['age'] < $b['age']) ? -1 : 1;
            });

            return $sorted_set;
            break;
        default:
            throw new InvalidArgumentException("Invalid order: {$order}. Use 'asc' or 'desc'.");
    }
}

// Example usage:

$people = [
    ['name' => 'Alice', 'address' => '123 Main St', 'age' => 30],
    ['name' => 'Bob', 'address' => '456 Elm St', 'age' => 28],
    ['name' => 'Charlie', 'address' => '789 Oak St', 'age' => 30]
];

try {
    $ascending_order = smart_sort_array($people, 'asc');
    print_r($ascending_order);

    $descending_order = smart_sort_array($people, 'desc');
    print_r($descending_order);
} catch (InvalidArgumentException $e) {
    echo "Error: " . $e->getMessage();
}
?>
```

