package main

import (
	"fmt"
	"io/ioutil"
	"os"

	"github.com/segmentio/avro/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <filename> <struct>")
		os.Exit(1)
	}

	filename := os.Args[1]
	structName := os.Args[2]

	inputFile, err := ioutil.ReadFile(filename)
	if err != nil {
		fmt.Printf("Error reading file %s: %v\n", filename, err)
		return
	}

	var structData interface{}

	err = json.Unmarshal(inputFile, &structData)
	if err != nil {
		fmt.Printf("Error unmarshalling JSON into structData: %v\n", err)
		return
	}

	// Assuming the struct has fields with simple types like int, string, etc.
	fieldSchema := make(map[string]*schema.Field)
	for fieldName, fieldValue := range structData.(map[string]interface{}) {
		fieldType := reflect.TypeOf(fieldValue).Kind()
		switch fieldType {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			fieldSchema[fieldName] = &schema.Field{Name: fieldName, Type: schema.TypeInt}
		case reflect.String:
			fieldSchema[fieldName] = &schema.Field{Name: fieldName, Type: schema.TypeString}
		default:
			fmt.Printf("Unsupported field type: %T\n", fieldValue)
			continue
		}
	}

	schemaBytes, err := schema.NewEncoder().Encode(schema.Schema{
		Fields: fieldSchema,
	})
	if err != nil {
		fmt.Printf("Error encoding schema: %v\n", err)
		return
	}

	outputFile, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		fmt.Printf("Error creating output file: %v\n", err)
		return
	}
	defer outputFile.Close()

	_, err = outputFile.Write(schemaBytes)
	if err != nil {
		fmt.Printf("Error writing to output file: %v\n", err)
		return
	}

	fmt.Printf("Generated Avro schema saved as %s.avsc\n", structName)
}
```

### How to Use:

1. Save this code snippet to a file, e.g., `script.go`.
2. Run the following command in your terminal to compile and execute the program:
   ```bash
   go run script.go [Go Source File Name] [Struct Name]
   ```
   For example:
   ```bash
   go run script.go mydatafile.go MyStruct
   ```

### Assumptions:
- The struct contains fields of basic types like integers (`int`, `int8`, `int16`, `int32`, `int64`), strings, booleans, arrays, maps, and other built-in types supported by Avro.
- The program assumes that the struct's fields have valid types (e.g., integer values instead of pointers).

### Notes:
- This program does not handle complex data structures or nested structs.
- If you need more advanced functionality (like handling unions, records, enums, etc.), additional libraries such as `github.com/tendermint/go-avropb` might be necessary.

